def _strip_quotes(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        return value[1:-1]
    return value


def _like_to_regex(pattern: str, ignore_case: bool) -> re.Pattern:
    regex = "^"
    for ch in pattern:
        if ch == "%":
            regex += ".*"
        elif ch == "_":
            regex += "."
        else:
            regex += re.escape(ch)
    regex += "$"
    return re.compile(regex, re.DOTALL | (re.IGNORECASE if ignore_case else 0))


def _cmp_str(actual: str | None, op: str, value: str) -> bool:
    if actual is None:
        return False
    if op == "=":
        return actual == value
    if op == "!=":
        return actual != value
    if op == "LIKE":
        return _like_to_regex(value, ignore_case=False).match(actual) is not None
    if op == "ILIKE":
        return _like_to_regex(value, ignore_case=True).match(actual) is not None
    raise MlflowException(
        f"Invalid comparator '{op}' for string attribute", error_code=INVALID_PARAMETER_VALUE
    )


def _cmp_num(actual: int | None, op: str, value: str) -> bool:
    if actual is None:
        return False
    try:
        target = int(value)
    except (TypeError, ValueError):
        raise MlflowException(
            f"Expected a numeric value but got '{value}'", error_code=INVALID_PARAMETER_VALUE
        )
    if op == "=":
        return actual == target
    if op == "!=":
        return actual != target
    if op == ">":
        return actual > target
    if op == ">=":
        return actual >= target
    if op == "<":
        return actual < target
    if op == "<=":
